"""E148 measured probe data and E144 privileged offline audit documentation."""
import shutil
from pathlib import Path
from .dense_joint_supervision import ROOT
from .history_estimator_control import ROOT as OLD
from .abstaining_task_value_gate import read,save,fingerprint

def run():
    s=read(ROOT/'summary.json');v=read(ROOT/'verification.json');metrics=read(ROOT/'prediction_summary.json');lines=['# E148: measured directional probe supervision','',f"Collected **{s['branches']}** single40ms branches from **{s['contexts']}** clean phase-entry histories across all96 fitting placements. Each active joint receives both signs of a fixed.01rad perturbation around measured holding bias. These are training-only reconstructed simulation states, not full task episodes or inference-time probes.",'','Histories remain fixed across each branch group. Labels are observed joint and tool displacement; no exact Jacobian label or simulator parameter enters the learned model. Full integrator state was not saved in E144, so these branches explicitly reconstruct qpos/qvel/preceding commands and reset warmstart; they are not claimed to be exact continuations of the original trajectories.','', 'All9,614 labels were reconstructed from saved branch states, and all signed-joint branches for eight representative contexts (one per fold/joint-count cell) were rerun exactly. Every phase-entry selection and history alignment was checked. No held/fresh placement was used.','', '| Frozen estimator | Position RMSE (mm) | Six joints | Seven joints |','|---|---:|---:|---:|']
    for name,m in metrics.items():lines.append(f"| {name} | {m['all']['position_rmse_mm']:.4f} | {m['6']['position_rmse_mm']:.4f} | {m['7']['position_rmse_mm']:.4f} |")
    lines+=['','These are new-direction prediction measurements, not task success. E146 remains better than its analytical prior on this label set, although its full task performance remains below E120 ensemble. E150 compares observed-only and mixed directional fine-tuning from identical initial weights on identical histories and splits.','', 'Source successes and failures are saved in the [E144 video gallery](../ease_history_estimator_control_v1/videos/index.html). Single-step training branches have no success/failure task label; all before/after states are saved under branches/.',''];(ROOT/'report.md').write_text('\n'.join(lines));report=Path(__file__).with_name('TECHNICAL_REPORT.md');text=report.read_text(encoding='utf-8');assert '## E148:' not in text;report.write_text(text+'\n## E148: measured directional probes\n\n'+lines[2]+f' All branch labels verified. Report: `{ROOT}/report.md`.\n',encoding='utf-8')
    diagnostic=OLD/'jacobian_diagnosis';m=read(diagnostic/'summary.json');(diagnostic/'report.md').write_text('# Privileged offline kinematic audit\n\nSaved pre-action fitting states only; exact simulator Jacobians were used for diagnostic comparison, never as controller inputs or learned targets. Learned E143 improves full-Jacobian and clipped exact-Jacobian-reference action error over uniform/constant estimators on identical histories, despite lower full-task success. The measured calibration prior improves these map errors further. This rules out the simple claim that lower executed-direction prediction error necessarily hid a worse full map on average; it does not establish causal task improvement. E149 tests the exact map in complete episodes.\n\n'+str(m)+'\n')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(8,4));ax.bar(list(metrics),[m['all']['position_rmse_mm'] for m in metrics.values()]);ax.set_ylabel('Directional position RMSE (mm)');ax.set_title('E148 | measured branch labels | fitting families');fig.tight_layout();fig.savefig(ROOT/'comparison.png',dpi=150);plt.close(fig);shutil.copy2(__file__,ROOT/'source'/Path(__file__).name);save(ROOT/'artifact_hashes.json',{str(p.relative_to(ROOT)):fingerprint(p) for p in ROOT.rglob('*') if p.is_file() and p.name!='artifact_hashes.json'});print('E148 and offline diagnostic reports saved',flush=True)

if __name__=='__main__':run()
